import collections

def second_largest(xs):
    if not isinstance(xs, list) or not xs: 
        return None

    dictionary = collections.Counter(xs)

    # To ensure second largest number is distinct, we need to find the second most common 
    # value, which may be identical to the largest number. So firstly we remove all 
